     const t=Math.max(0,Math.min(1,.55+.50*(x/width-.5)-.60*(y/height-.5))),a=t<.5?stops[0]:stops[1],b=t<.5?stops[1]:stops[2],mix=t<.5?t*2:(t-.5)*2;
